From 94002def049ee2bcc860a94ce54351d45325023b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:56:53 +0100
Subject: [PATCH] applets/taskmanager: make thumbnail tooltips resizable from
 their edges

Window thumbnails in task tooltips had a fixed size, too small to see much
on many screens. Dragging any edge not facing the panel now resizes the
tooltip like Kickoff and the system tray, and the size is remembered.

BUG: 526187
---
 applets/taskmanager/main.xml                |  8 ++
 applets/taskmanager/qml/ToolTipDelegate.qml | 91 ++++++++++++++++++++-
 applets/taskmanager/qml/ToolTipInstance.qml |  2 +-
 3 files changed, 98 insertions(+), 3 deletions(-)

diff --git a/applets/taskmanager/main.xml b/applets/taskmanager/main.xml
index 8c3b68785b..e34800352f 100644
--- a/applets/taskmanager/main.xml
+++ b/applets/taskmanager/main.xml
@@ -75,6 +75,14 @@
       <label>Whether to show tooltips when hovering task buttons.</label>
       <default>true</default>
     </entry>
+    <entry name="toolTipWidth" type="Int">
+      <label>The width of each window in tooltips with window thumbnails, set by dragging the tooltip's edges. 0 means the default width.</label>
+      <default>0</default>
+    </entry>
+    <entry name="toolTipThumbnailHeight" type="Int">
+      <label>The height of window thumbnails in tooltips, set by dragging the tooltip's edges. 0 means the default height.</label>
+      <default>0</default>
+    </entry>
     <entry name="taskMaxWidth" type="Enum">
       <label>Tune the max width of task items.</label>
       <choices>
diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..116d7e7503 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -53,8 +53,13 @@ Loader {
     property bool blockingUpdates: false

     readonly property bool isVerticalPanel: Plasmoid.formFactor === PlasmaCore.Types.Vertical
+    // Tooltips with window thumbnails can be resized by dragging their edges
+    readonly property bool resizable: isWin && Plasmoid.configuration.showToolTips
     // This number controls the overall size of the window tooltips
-    readonly property int tooltipInstanceMaximumWidth: Kirigami.Units.gridUnit * 16
+    readonly property int tooltipInstanceMaximumWidth: resizable && Plasmoid.configuration.toolTipWidth > 0
+        ? Plasmoid.configuration.toolTipWidth : Kirigami.Units.gridUnit * 16
+    readonly property int thumbnailHeight: resizable && Plasmoid.configuration.toolTipThumbnailHeight > 0
+        ? Plasmoid.configuration.toolTipThumbnailHeight : Kirigami.Units.gridUnit * 8

     // These properties are required to make tooltip interactive when there is a player but no window is present.
     readonly property Mpris.PlayerContainer playerData: mpris2Source.playerForLauncherUrl(launcherUrl, pidParent)
@@ -67,6 +72,88 @@ Loader {

     sourceComponent: isGroup ? groupToolTip : singleTooltip

+    component ResizeHandle: MouseArea {
+        required property int edge
+        readonly property bool horizontal: edge === Qt.LeftEdge || edge === Qt.RightEdge
+        // Reach out into the tooltip's own margins, where its visible edge is
+        readonly property real padding: {
+            const window = Window.window as PlasmaCore.Window;
+            if (!window) {
+                return 0;
+            }
+            switch (edge) {
+            case Qt.TopEdge: return window.topPadding;
+            case Qt.BottomEdge: return window.bottomPadding;
+            case Qt.LeftEdge: return window.leftPadding;
+            default: return window.rightPadding;
+            }
+        }
+        // Along the panel the tooltip is centered on its task, and a group tooltip lists its windows there
+        readonly property bool alongPanel: horizontal !== toolTipDelegate.isVerticalPanel
+        property int pressSize
+        property real pressWindowSize
+        property point pressPosition
+
+        // Not on the edge facing the panel
+        visible: toolTipDelegate.resizable && toolTipDelegate.status === Loader.Ready
+            && !(edge === Qt.TopEdge && Plasmoid.location === PlasmaCore.Types.TopEdge)
+            && !(edge === Qt.BottomEdge && Plasmoid.location === PlasmaCore.Types.BottomEdge)
+            && !(edge === Qt.LeftEdge && Plasmoid.location === PlasmaCore.Types.LeftEdge)
+            && !(edge === Qt.RightEdge && Plasmoid.location === PlasmaCore.Types.RightEdge)
+        z: 1
+        cursorShape: horizontal ? Qt.SizeHorCursor : Qt.SizeVerCursor
+
+        anchors {
+            top: edge === Qt.BottomEdge ? undefined : parent.top
+            bottom: edge === Qt.TopEdge ? undefined : parent.bottom
+            left: edge === Qt.RightEdge ? undefined : parent.left
+            right: edge === Qt.LeftEdge ? undefined : parent.right
+            topMargin: edge === Qt.TopEdge ? -padding : 0
+            bottomMargin: edge === Qt.BottomEdge ? -padding : 0
+            leftMargin: edge === Qt.LeftEdge ? -padding : 0
+            rightMargin: edge === Qt.RightEdge ? -padding : 0
+        }
+        width: horizontal ? padding + Kirigami.Units.smallSpacing : undefined
+        height: horizontal ? undefined : padding + Kirigami.Units.smallSpacing
+
+        onPressed: mouse => {
+            pressSize = horizontal ? toolTipDelegate.tooltipInstanceMaximumWidth : toolTipDelegate.thumbnailHeight;
+            pressWindowSize = horizontal ? Window.width : Window.height;
+            pressPosition = mapToGlobal(mouse.x, mouse.y);
+        }
+        onPositionChanged: mouse => {
+            const position = mapToGlobal(mouse.x, mouse.y);
+            let size;
+            if (alongPanel) {
+                // Make the dragged edge follow the pointer: the tooltip grows on both sides of the
+                // task's center until it reaches the screen edge, and then only on the other side
+                const taskCenter = toolTipDelegate.parentTask.mapToGlobal(toolTipDelegate.parentTask.width / 2, toolTipDelegate.parentTask.height / 2);
+                const pointer = horizontal ? position.x : position.y;
+                const center = horizontal ? taskCenter.x : taskCenter.y;
+                const screenStart = horizontal ? Screen.virtualX : Screen.virtualY;
+                const screenEnd = screenStart + (horizontal ? Screen.width : Screen.height);
+                const windowSize = edge === Qt.RightEdge || edge === Qt.BottomEdge
+                    ? Math.min(2 * (pointer - center), pointer - screenStart)
+                    : Math.min(2 * (center - pointer), screenEnd - pointer);
+                const count = toolTipDelegate.isGroup ? Math.max(1, toolTipDelegate.windows.length) : 1;
+                size = Math.round(pressSize + (windowSize - pressWindowSize) / count);
+            } else {
+                const delta = horizontal ? position.x - pressPosition.x : position.y - pressPosition.y;
+                size = pressSize + (edge === Qt.LeftEdge || edge === Qt.TopEdge ? -delta : delta);
+            }
+            if (horizontal) {
+                Plasmoid.configuration.toolTipWidth = Math.max(Kirigami.Units.gridUnit * 10, Math.min(size, Screen.width / 2));
+            } else {
+                Plasmoid.configuration.toolTipThumbnailHeight = Math.max(Kirigami.Units.gridUnit * 4, Math.min(size, Screen.height / 2));
+            }
+        }
+    }
+
+    ResizeHandle { edge: Qt.TopEdge }
+    ResizeHandle { edge: Qt.BottomEdge }
+    ResizeHandle { edge: Qt.LeftEdge }
+    ResizeHandle { edge: Qt.RightEdge }
+
     Component {
         id: singleTooltip

@@ -149,7 +236,7 @@ Loader {

                 // On Wayland, a tooltip has a significant resizing process, so estimate the size first.
                 readonly property real estimatedWidth: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? 1 : count) * (toolTipDelegate.tooltipInstanceMaximumWidth + Kirigami.Units.gridUnit) - Kirigami.Units.gridUnit
-                readonly property real estimatedHeight: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? count : 1) * (Plasmoid.configuration.showToolTips ? (toolTipDelegate.tooltipInstanceMaximumWidth / 2 + Kirigami.Units.gridUnit) : Kirigami.Units.gridUnit * 2) - Kirigami.Units.gridUnit
+                readonly property real estimatedHeight: (toolTipDelegate.isVerticalPanel || !Plasmoid.configuration.showToolTips ? count : 1) * (Plasmoid.configuration.showToolTips ? (toolTipDelegate.thumbnailHeight + Kirigami.Units.gridUnit) : Kirigami.Units.gridUnit * 2) - Kirigami.Units.gridUnit

                 model: tasksModel

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..67692cf1cc 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -287,7 +287,7 @@ ColumnLayout {
         id: thumbnailSourceItem

         Layout.fillWidth: true
-        Layout.preferredHeight: Kirigami.Units.gridUnit * 8
+        Layout.preferredHeight: toolTipDelegate.thumbnailHeight

         clip: true
         visible: Plasmoid.configuration.showToolTips && toolTipDelegate.isWin
-- 
